type SubscriptionStatus = 'trial' | 'active' | 'cancelled' | 'expired';

class SubscriptionStateMachine {
  canTransition(from: SubscriptionStatus, to: SubscriptionStatus): boolean {
    const validTransitions = {
      trial: ['active', 'cancelled'],
      active: ['cancelled', 'expired'],
      cancelled: ['active'],
      expired: ['active']
    };
    return validTransitions[from]?.includes(to) ?? false;
  }

  applyTransition(subscription: Subscription, newStatus: SubscriptionStatus): Subscription {
    if (!this.canTransition(subscription.status, newStatus)) {
      throw new InvalidStateTransitionError(subscription.status, newStatus);
    }
    return { ...subscription, status: newStatus, updatedAt: new Date() };
  }
}

